-- Lagoas: portos de barco (píer + margem oposta em cada grande lagoa, mais o Porto de Valen), viagem de barco validada no servidor
-- (travessia 15 gold, viagem entre portos 50-250 gold pela distância), pesca rara nos píeres (peixe prateado e dourado),
-- e as linhas da grade de territórios que mudaram com o rio novo ao lado de Porto de Valen. Só acrescenta/atualiza.

on conflict (row) do update set cells = excluded.cells;

create table if not exists boat_ports(id text primary key, name text not null, lake text, x int not null, y int not null);
alter table boat_ports enable row level security;
drop policy if exists boat_ports_read on boat_ports; create policy boat_ports_read on boat_ports for select using (true);
on conflict (id) do update set name = excluded.name, lake = excluded.lake, x = excluded.x, y = excluded.y;


-- viagem de barco: só falando com o barqueiro no píer (posição informada perto do porto de saída)
create or replace function boat_travel(p_from text, p_to text) returns jsonb language plpgsql security definer set search_path = public as $$
declare c characters; a boat_ports; b boat_ports; cfgb jsonb := cfg('boats'); cost bigint; g bigint; z jsonb;
begin
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  select * into a from boat_ports where id = p_from; select * into b from boat_ports where id = p_to;
  if a.id is null or b.id is null or a.id = b.id then raise exception 'rota inválida'; end if;
  if c.task = 'hunt' then raise exception 'saia da caça antes de embarcar'; end if;
  if c.pos_at is null or c.pos_at < now() - interval '2 minutes' or sqrt(power(c.x - a.x, 2) + power(c.y - a.y, 2)) > (cfgb ->> 'range')::numeric then raise exception 'fale com o barqueiro no píer'; end if;
  cost := case when a.lake is not null and a.lake = b.lake then (cfgb ->> 'cross')::bigint
    else least((cfgb ->> 'max')::bigint, greatest((cfgb ->> 'min')::bigint, round((cfgb ->> 'min')::numeric + sqrt(power(a.x - b.x, 2) + power(a.y - b.y, 2)) / (cfgb ->> 'per_tiles')::numeric)::bigint)) end;
  select gold into g from wallets where character_id = c.id for update; if g < cost then raise exception 'a viagem custa % gold', cost; end if;
  perform add_gold(c.id, -cost, 'barco', b.id);
  z := zone_at(b.x, b.y);
  update characters set x = b.x, y = b.y, pos_at = now(), city_id = z ->> 'city', ring = (z ->> 'ring')::int, pvp_mode = case when (z ->> 'ring')::int = 1 then false else pvp_mode end where id = c.id;
  return jsonb_build_object('x', b.x, 'y', b.y, 'cost', cost, 'to', b.name);
end $$;
grant execute on function boat_travel(text, text) to authenticated;

